const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=['让服务，从被动响应转向主动协同','三类断点，正在拉长服务周期','本次方案的范围与成功标准','24 页，讲清一条服务闭环','从报修到解决，重新连接每个环节','现场事实：信息散落在五种工具','一条工单，让现场与中心同步工作','协同中枢：统一任务，而非统一工具','服务网络：让能力抵达每个现场','把客户问题，转成可执行的工作','派工策略：经验与约束共同决策','现场作业：每一步都有依据','异常升级：保留问题的完整来路','知识沉淀：从一次解决到重复使用','从服务过程，找到经营改善机会','三组指标，衡量闭环是否有效','数据边界：信息只到需要的人','连接现有系统，保留业务连续性','先跑通一个区域，再逐步扩展','试点节奏与每一阶段的出口','责任地图：谁判断，谁执行','关键风险与回退安排','验收清单：用真实工单检验方案','下一步，从一个真实服务现场开始'];
