const chapters=['01 业务起点','02 协同方案','03 工作闭环','04 数据与连接','05 试点与治理','06 验收与行动'];
const bullets=[['统一服务事实','缩短协同等待','留下复用依据'],['信息重复录入','状态无法同步','经验难以复用'],['区域服务团队','两类高频工单','完整闭环验证'],['理解现状','建立方案','试点落地']];
const pages=titles.map((title,i)=>({id:i+1,title,sub:subtitles[i],chapter:Math.floor(i/4),layout:i%6,body:bullets[i%4],image:i<20,svg:i<16,ppt:i<12,prompt:i!==18,drift:i===7||i===8}));
