function runsView(){return head('任务与交付','意见和生成请求先进入待交接。只有真实接手记录，才会变为处理中。',button('回整稿','nav-gallery'),'任务与交付')+`<div class="runtime-layout"><section><div class="section-head"><h2>制作任务</h2><span class="small-text muted">${state.tasks.length} 条记录</span></div>${state.tasks.length?state.tasks.map((t,i)=>`<article class="run-item"><div class="row between"><h3>${esc(t.title)}</h3>${tag(statusText(t),statusType(t))}</div><p class="muted">${esc(t.note)}</p><div class="run-meta">第 ${t.pages.join('、')} 页 · ${t.baseRevision} · ${stageName(t.targetStage)} · ${t.pages.map(id=>artifactRef(t.bases[id])).join('、')} · TASK-${t.id}${t.batchId?' · '+t.batchId:''} · ${esc(t.kind)} · 创建于本次演示</div><div class="trace"><span class="${['queued','copied'].includes(t.status)?'current':''}">你发送交接</span><span>${uiIcon("right")}</span><span class="${t.status==='running'?'current':''}">制作工具处理</span><span>${uiIcon("right")}</span><span class="${t.status==='returned'?'current':''}">你核对候选</span><span>${uiIcon("right")}</span><span>采用并继续制作</span></div><div class="run-actions">${['queued','copied'].includes(t.status)?button('复制制作要求','task-copy-'+i,'primary'):''}${t.candidates?button('查看候选并比较','task-compare-'+i,'primary'):''}${['queued','copied','running'].includes(t.status)?button('取消任务','task-cancel-'+i,''):''}${['failed','cancelled','kept'].includes(t.status)?button('新建重试请求','retry-task-'+i):''}${t.style?button('查看固定请求','task-open-'+i,'quiet'):''}${button('看关联页面','page-'+t.pages[0]+'-'+t.targetStage,'quiet')}</div>${['queued','copied','running'].includes(t.status)?``:''}</article>`).join(''):`<div class="zero-state"><h3>还没有待交接任务</h3><p style="margin:10px 0 20px">从任何页面提出修改，或先校准第 8、9 页的风格。</p>${button('开始风格校准','nav-style','primary')}</div>`}<div class="footer-note">取消任务后返回的结果不会替换当前稿。</div></section><aside><div class="section-head"><h2>固定版本导出</h2></div><section class="panel"><div class="panel-body"><label class="label" for="export-version">本次文件使用的版本</label><select data-od-id="select-48376" id="export-version" data-input="export-version" style="width:100%"><option value="R18" ${state.exportVersion==='R18'?'selected':''}>R18 · 当前版本</option><option value="R16" ${state.exportVersion==='R16'?'selected':''}>R16 · 历史快照</option></select><p class="form-hint">导出启动后固定版本，新结果不会进入同一个文件。</p><div class="file-item"><h3>审阅文件</h3><p>现有稿件和预览，附缺项说明；可外发，不包含内部执行材料。</p>${button('预览审阅包清单','export-review','', 'style="width:100%"')}</div><div class="file-item"><h3>交付文件 ${tag('未就绪','warn')}</h3><p>12 页缺少 PPT 预览；第 8、9 页风格待确认。由实际检查共同判断。</p>${button('定位缺项页面 →','missing-ppt','text-link')}</div><div class="file-item"><h3>工程包</h3><p>保留材料、过程输入和历史产物，供继续制作与恢复。</p>${button('预览工程包清单','export-engineering','', 'style="width:100%"')}</div></div></section><p class="form-hint">导出服务未连接，目前可查看文件清单。</p></aside></div>`}
